import { describe, expect, test } from "bun:test";
import { greet, add, slugify } from "./utils";

describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });
});

describe("slugify", () => {
  test("converts uppercase text to lowercase", () => {
    expect(slugify("HELLO")).toBe("hello");
    expect(slugify("UPPERCASE")).toBe("uppercase");
    expect(slugify("FooBar")).toBe("foobar");
  });

  test("replaces spaces with hyphens", () => {
    expect(slugify("Hello World")).toBe("hello-world");
    expect(slugify("  Foo  Bar  ")).toBe("foo-bar");
  });

  test("replaces underscores with hyphens", () => {
    expect(slugify("Foo_Bar")).toBe("foo-bar");
    expect(slugify("Foo__Bar")).toBe("foo-bar");
    expect(slugify("Foo_Bar Baz")).toBe("foo-bar-baz");
  });

  test("removes special characters and punctuation", () => {
    expect(slugify("Hello, World!")).toBe("hello-world");
    expect(slugify("Price: $99.99")).toBe("price-99-99");
    expect(slugify("!!!Alert!!!")).toBe("alert");
  });

  test("collapses consecutive hyphens to single hyphen", () => {
    expect(slugify("a---b")).toBe("a-b");
    expect(slugify("Hello,  World!")).toBe("hello-world");
  });

  test("trims leading and trailing hyphens", () => {
    expect(slugify("  Hello  ")).toBe("hello");
    expect(slugify("-already-slugified-")).toBe("already-slugified");
  });

  test("preserves numbers", () => {
    expect(slugify("Report 2024")).toBe("report-2024");
    expect(slugify("Q&A Report 2024")).toBe("qa-report-2024");
  });

  test("handles empty strings", () => {
    expect(slugify("")).toBe("");
  });

  test("is idempotent", () => {
    const input = "Hello, World!";
    const slugged = slugify(input);
    expect(slugify(slugged)).toBe(slugged);
  });
});

